-- Restore omitted priest and Research Access teaching rewards
-- 2026_11_10_51_world_everlake_class_quest_learning.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): eg-link 9fcae73cc74fea4f1c4f, wago 1.60.1.70862
-- Written against the fork world core 343fe6fb + world-data 24a3b39e + reviewed drafts.
-- Efficient Games CC BY 4.0. Restore explicit reward fields; do not change quest activation, restrictions or NPC relations. Research Access hidden-quest activation remains unverified.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';
SET SESSION autocommit = 0;
CREATE TEMPORARY TABLE `everlake_class_learning` (
 `quest` int unsigned NOT NULL PRIMARY KEY,`reward` int unsigned NOT NULL,`class_mask` int unsigned NOT NULL,
 `race_mask` bigint unsigned NOT NULL,`starter` int unsigned NOT NULL,`ender` int unsigned NOT NULL);
INSERT INTO `everlake_class_learning` (`quest`,`reward`,`class_mask`,`race_mask`,`starter`,`ender`) VALUES
(94775,1277387,16,1,3600,376),
(94776,1277387,16,1,1226,376),
(94777,1277387,16,1,11397,376),
(94820,1277663,16,64,11401,258785),
(97286,1302696,128,12884902143,211033,211033);
UPDATE `quest_template` q JOIN `everlake_class_learning` s ON s.`quest`=q.`ID`
JOIN `quest_template_addon` a ON a.`ID`=q.`ID` AND a.`AllowableClasses`=s.`class_mask`
SET q.`RewardSpell`=s.`reward`
WHERE q.`RewardSpell`=0 AND q.`AllowableRaces`=s.`race_mask`
AND ((q.`ID` IN (94775,94776,94777) AND q.`LogTitle`='Divine Grace') OR (q.`ID`=94820 AND q.`LogTitle`='Contingency Plan') OR (q.`ID`=97286 AND q.`LogTitle`='Research Access'))
AND EXISTS (SELECT 1 FROM `creature_queststarter` st JOIN `creature` c ON c.`id`=st.`id` JOIN `creature_template` t ON t.`entry`=c.`id`
 WHERE st.`quest`=q.`ID` AND st.`id`=s.`starter` AND (COALESCE(c.`npcflag`,t.`npcflag`)&2)=2)
AND EXISTS (SELECT 1 FROM `creature_questender` en JOIN `creature` c ON c.`id`=en.`id` JOIN `creature_template` t ON t.`entry`=c.`id`
 WHERE en.`quest`=q.`ID` AND en.`id`=s.`ender` AND (COALESCE(c.`npcflag`,t.`npcflag`)&2)=2)
AND (q.`ID`=97286 OR (q.`ID`=94820 AND EXISTS (SELECT 1 FROM `spell_script_names` WHERE `spell_id`=1277462 AND `ScriptName`='classic_spell_pri_contingency_plan'))
 OR (q.`ID` IN (94775,94776,94777) AND EXISTS (SELECT 1 FROM `spell_script_names` WHERE `spell_id`=1277370 AND `ScriptName`='classic_spell_pri_divine_grace')));

-- Captured current-core spell reward displays
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`QuestID` int unsigned NOT NULL, `Idx` int unsigned NOT NULL, `SpellID` int unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `Type` int unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`QuestID`, `Idx`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`QuestID`, `Idx`, `SpellID`, `PlayerConditionID`, `Type`, `VerifiedBuild`, `note`) VALUES
(94775, 0, 1277370, 0, 0, 0, 'Captured EG Link 70862 explicit quest reward display; pinned learn-spell effect'),
(94776, 0, 1277370, 0, 0, 0, 'Captured EG Link 70862 explicit quest reward display; pinned learn-spell effect'),
(94777, 0, 1277370, 0, 0, 0, 'Captured EG Link 70862 explicit quest reward display; pinned learn-spell effect'),
(94820, 0, 1277462, 0, 0, 0, 'Captured EG Link 70862 explicit quest reward display; pinned learn-spell effect'),
(97286, 0, 1302508, 0, 3, 0, 'Captured EG Link 70862 explicit quest reward display; pinned learn-spell effect');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `quest_reward_display_spell` t WHERE t.`QuestID` = s.`QuestID` AND t.`Idx` = s.`Idx`) AND EXISTS (SELECT 1 FROM `quest_template` q JOIN `everlake_class_learning` c ON c.`quest`=q.`ID` WHERE q.`ID`=s.`QuestID` AND q.`RewardSpell`=c.`reward`);
INSERT INTO `quest_reward_display_spell` (`QuestID`, `Idx`, `SpellID`, `PlayerConditionID`, `Type`, `VerifiedBuild`) SELECT `QuestID`, `Idx`, `SpellID`, `PlayerConditionID`, `Type`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `file`, `note`) SELECT 'quest_reward_display_spell', s.`QuestID`, s.`Idx`, '2026_11_10_51_world_everlake_class_quest_learning.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_51_world_everlake_class_quest_learning.sql', `note` = s.`note`;
DROP TEMPORARY TABLE `everlake_import_stage`;

DROP TEMPORARY TABLE `everlake_class_learning`;
